-- ============================================================================
-- Rangements : chaque modèle de questions et chaque exercice dans l'arbre des notions
-- (ADR 0019), et le type de source des exercices.
-- ============================================================================
-- Source de vérité : docs/wip/arbre-notions/correspondance/modeles.csv et exercices.csv,
-- VALIDÉS par David (lots 1-4, 2026-10-07 ; 7 cibles mises à jour le 2026-10-09 après la
-- restructuration C2 de la branche Logique). Livraison par migration de données : décision
-- de David du 2026-10-09. Fichier GÉNÉRÉ — ne pas éditer à la main.
--   * 1005 modèles → question_templates.classification_node_id (un nœud chacun) ;
--   * 328 exercices → 450 lignes de exercise_classifications (le premier nœud
--     est le principal) ; l'exercice « debug » reste exclu (aucun nœud) ;
--   * types de source « Bac » et « Concours » créés, rattachés à 8 exercices.
--
-- Les modèles et exercices n'existent qu'en production : en base locale (vide), la migration
-- ne range rien et ses vérifications le tolèrent ; elle exige en revanche TOUT ou RIEN (une
-- présence partielle des identifiants fait échouer la migration). Elle est prouvée par
-- tests/integration/rangements-modeles-exercices.test.ts, qui fabrique des copies des
-- identifiants de la prod puis rejoue CE fichier.
--
-- La résolution des chemins est STRICTE : une sous-notion introuvable fait échouer la
-- migration (elle ne retombe jamais sur la notion).
--
-- `updated_at` est PRÉSERVÉ : un rangement est une métadonnée, pas une modification du
-- contenu. Les deux triggers de date sont suspendus le temps du remplissage puis rétablis ;
-- les triggers de contrôle du nœud (classification_target_is_leafish) restent actifs.
--
-- Accès : aucun changement (colonnes et table créées par 20261007120000, droits inchangés).
--
-- Rollback (valable tant qu'aucun rangement n'a été saisi à la main depuis — il n'existe
-- pas encore d'interface pour le faire) :
--   delete from public.exercise_classifications;
--   alter table public.question_templates disable trigger update_question_templates_updated_at;
--   update public.question_templates set classification_node_id = null where classification_node_id is not null;
--   alter table public.question_templates enable trigger update_question_templates_updated_at;
--   alter table public.exercises disable trigger exercises_updated_at;
--   update public.exercises set source_type_id = null where source_type_id is not null;
--   alter table public.exercises enable trigger exercises_updated_at;
--   delete from public.source_types where name in ('Bac', 'Concours');
-- Aucune donnée d'élève n'est touchée, ni par la migration ni par son rollback.
-- ============================================================================

-- ---- 0. Garde : rien n'est déjà rangé (sinon ce remplissage écraserait une saisie) ----
do $garde$
begin
	if exists (select 1 from public.question_templates where classification_node_id is not null)
	   or exists (select 1 from public.exercise_classifications)
	   or exists (select 1 from public.exercises where source_type_id is not null) then
		raise exception 'rangements déjà présents : remplissage refusé';
	end if;
end $garde$;

-- ---- 1. La correspondance, en tables temporaires ----------------------------------
drop table if exists pg_temp._rg_modeles;
drop table if exists pg_temp._rg_exercices;
create temporary table _rg_modeles (id uuid primary key, branche text not null, notion text not null, sous_notion text);
create temporary table _rg_exercices (
	exercise_id uuid not null, branche text not null, notion text not null, sous_notion text,
	is_primary boolean not null, position integer not null, type_source text
);

-- ---- 2. Résolution STRICTE des chemins (branche → notion → sous-notion) ---------------
create temporary table _rg_modeles_noeuds as 
	select r.*, case when r.sous_notion is null then nn.id else s.id end as node_id
	  from _rg_modeles r
	  left join public.classification_nodes b on b.kind = 'branch' and b.parent_id is null and b.name = r.branche
	  left join public.classification_nodes nn on nn.kind = 'notion' and nn.parent_id = b.id and nn.name = r.notion
	  left join public.classification_nodes s on s.kind = 'subnotion' and s.parent_id = nn.id and s.name = r.sous_notion;
create temporary table _rg_exercices_noeuds as 
	select r.*, case when r.sous_notion is null then nn.id else s.id end as node_id
	  from _rg_exercices r
	  left join public.classification_nodes b on b.kind = 'branch' and b.parent_id is null and b.name = r.branche
	  left join public.classification_nodes nn on nn.kind = 'notion' and nn.parent_id = b.id and nn.name = r.notion
	  left join public.classification_nodes s on s.kind = 'subnotion' and s.parent_id = nn.id and s.name = r.sous_notion;
do $resolution$
declare v_m integer; v_e integer;
begin
	select count(*) into v_m from _rg_modeles_noeuds where node_id is null;
	select count(*) into v_e from _rg_exercices_noeuds where node_id is null;
	if v_m <> 0 or v_e <> 0 then
		raise exception 'chemins introuvables dans l''arbre : % modèle(s), % rangement(s) d''exercice', v_m, v_e;
	end if;
end $resolution$;

-- ---- 3. Types de source -------------------------------------------------------------
select v.name, v.position from (values ('Bac', 1), ('Concours', 2)) as v(name, position)
 where not exists (select 1 from public.source_types t where lower(t.name) = lower(v.name));

-- ---- 4. Remplissage, `updated_at` préservé ---------------------------------------------
alter table public.question_templates disable trigger update_question_templates_updated_at;
alter table public.exercises disable trigger exercises_updated_at;

update public.question_templates q set classification_node_id = r.node_id
  from _rg_modeles_noeuds r
 where q.id = r.id;

select r.exercise_id, r.node_id, r.is_primary, r.position
  from _rg_exercices_noeuds r
  join public.exercises x on x.id = r.exercise_id;

update public.exercises x set source_type_id = t.id
  from (select distinct exercise_id, type_source from _rg_exercices where type_source is not null) r
  join public.source_types t on lower(t.name) = lower(r.type_source)
 where x.id = r.exercise_id;

alter table public.question_templates enable trigger update_question_templates_updated_at;
alter table public.exercises enable trigger exercises_updated_at;

-- ---- 5. Vérifications : TOUT ou RIEN ------------------------------------------------
do $check$
declare
	v_m_presents integer; v_m_ranges integer;
	v_e_presents integer; v_e_lignes integer; v_e_attendues integer; v_e_principaux integer;
	v_types_attendus integer; v_types integer;
begin
	select count(*) into v_m_presents from _rg_modeles r join public.question_templates q on q.id = r.id;
	select count(*) into v_m_ranges from _rg_modeles_noeuds r join public.question_templates q on q.id = r.id
	 where q.classification_node_id = r.node_id;
	select count(distinct r.exercise_id) into v_e_presents from _rg_exercices r join public.exercises x on x.id = r.exercise_id;
	select count(*) into v_e_attendues from _rg_exercices r join public.exercises x on x.id = r.exercise_id;
	select count(*) into v_e_lignes from _rg_exercices_noeuds r
	  join public.exercise_classifications c on c.exercise_id = r.exercise_id and c.node_id = r.node_id
	   and c.is_primary = r.is_primary and c.position = r.position;
	select count(*) into v_e_principaux from public.exercise_classifications where is_primary;
	select count(distinct r.exercise_id) into v_types_attendus from _rg_exercices r join public.exercises x on x.id = r.exercise_id
	 where r.type_source is not null;
	select count(*) into v_types from public.exercises where source_type_id is not null;
	if v_m_presents not in (0, 1005) or v_e_presents not in (0, 328) then
		raise exception 'identifiants partiellement présents : % modèle(s) sur 1005, % exercice(s) sur 328', v_m_presents, v_e_presents;
	end if;
	if v_m_ranges <> v_m_presents or v_e_lignes <> v_e_attendues or v_e_principaux <> v_e_presents or v_types <> v_types_attendus then
		raise exception 'rangements incohérents : modèles %/%, lignes d''exercices %/%, principaux %/%, types de source %/%',
			v_m_ranges, v_m_presents, v_e_lignes, v_e_attendues, v_e_principaux, v_e_presents, v_types, v_types_attendus;
	end if;
	if (select count(*) from public.source_types where name in ('Bac', 'Concours')) <> 2 then
		raise exception 'types de source absents';
	end if;
end $check$;

drop table _rg_modeles_noeuds;
drop table _rg_exercices_noeuds;
drop table _rg_modeles;
drop table _rg_exercices;
